import{_ as a,o as t,c as o,a6 as s}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"日期与时间","description":"IMF-fixdate 与两种废弃格式、Date 字段的生成规则与时钟偏差处理。","frontmatter":{"title":"日期与时间","description":"IMF-fixdate 与两种废弃格式、Date 字段的生成规则与时钟偏差处理。","source":"https://daiw.org/manual/http11/http-date"},"headers":[],"relativePath":"manual/computer-programming/http11/http-date.md","filePath":"manual/computer-programming/http11/http-date.md"}'),n={name:"manual/computer-programming/http11/http-date.md"};function d(i,e,c,r,l,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="日期与时间" tabindex="-1">日期与时间 <a class="header-anchor" href="#日期与时间" aria-label="Permalink to &quot;日期与时间&quot;">​</a></h1><h2 id="http-date-的三种格式" tabindex="-1">HTTP-date 的三种格式 <a class="header-anchor" href="#http-date-的三种格式" aria-label="Permalink to &quot;HTTP-date 的三种格式&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP-date = IMF-fixdate / obs-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>接收方 <strong>MUST</strong> 接受全部三种；发送方 <strong>MUST</strong> 只生成 IMF-fixdate。</p><h3 id="imf-fixdate-唯一可生成的格式" tabindex="-1">IMF-fixdate（唯一可生成的格式） <a class="header-anchor" href="#imf-fixdate-唯一可生成的格式" aria-label="Permalink to &quot;IMF-fixdate（唯一可生成的格式）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IMF-fixdate = day-name &quot;,&quot; SP date1 SP time-of-day SP GMT</span></span>
<span class="line"><span>date1       = day SP month SP year        ; 例 02 Jun 1982</span></span>
<span class="line"><span>day         = 2DIGIT</span></span>
<span class="line"><span>year        = 4DIGIT</span></span>
<span class="line"><span>time-of-day = hour &quot;:&quot; minute &quot;:&quot; second  ; 均 2DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Date: Sun, 06 Nov 1994 08:49:37 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>固定长度 <strong>29 字节</strong>，逐字节要求：</p><ul><li>日、时、分、秒均为<strong>两位</strong>，不足补零（<code>06</code> 而非 <code>6</code>）。</li><li>年为<strong>四位</strong>。</li><li><code>day-name</code> 与 <code>month</code> 是<strong>大小写敏感</strong>的固定缩写：<code>Mon</code>/<code>Tue</code>/<code>Wed</code>/<code>Thu</code>/<code>Fri</code>/<code>Sat</code>/<code>Sun</code>；<code>Jan</code>/<code>Feb</code>/<code>Mar</code>/<code>Apr</code>/<code>May</code>/<code>Jun</code>/<code>Jul</code>/<code>Aug</code>/<code>Sep</code>/<code>Oct</code>/<code>Nov</code>/<code>Dec</code>。</li><li>时区<strong>必须</strong>是字面量 <code>GMT</code>，不接受 <code>UTC</code>、<code>+0000</code> 或任何偏移。</li><li>分隔符必须是单个 SP，逗号后必须有 SP。</li></ul><h3 id="obs-date-rfc-850-格式" tabindex="-1">obs-date：RFC 850 格式 <a class="header-anchor" href="#obs-date-rfc-850-格式" aria-label="Permalink to &quot;obs-date：RFC 850 格式&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Date: Sunday, 06-Nov-94 08:49:37 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>两位年份</strong>——存在世纪歧义。接收方遇到看起来比当前时间晚 50 年以上的日期，<strong>MUST</strong> 按上个世纪解释。</p><h3 id="obs-date-asctime-格式" tabindex="-1">obs-date：asctime 格式 <a class="header-anchor" href="#obs-date-asctime-格式" aria-label="Permalink to &quot;obs-date：asctime 格式&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Date: Sun Nov  6 08:49:37 1994</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>C 语言 <code>asctime()</code> 输出。特征：<strong>无时区</strong>（隐含 GMT）、日期为个位时用<strong>空格填充</strong>（<code>Nov 6</code> 中有两个空格）。解析器若按单空格分割会出错。</p><h2 id="解析要求" tabindex="-1">解析要求 <a class="header-anchor" href="#解析要求" aria-label="Permalink to &quot;解析要求&quot;">​</a></h2><ul><li>无效或无法解析的日期值 <strong>MUST</strong> 被当作<strong>无效</strong>处理，而非当前时间或 epoch。</li><li>缓存收到无效 <code>Expires</code> 时，<strong>MUST</strong> 视为已过期（保守策略）。</li><li>秒值允许 <code>60</code>（闰秒）。</li><li>所有 HTTP 时间戳<strong>恒为 GMT</strong>，不带本地时区概念。</li></ul><h2 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Date = HTTP-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>报文<strong>生成时刻</strong>（不是资源修改时刻）。</p><p>生成规则：</p><ul><li>有时钟的源服务器 <strong>MUST</strong> 在 <code>2xx</code>/<code>3xx</code>/<code>4xx</code> 响应中发送 <code>Date</code>。</li><li><code>1xx</code> 与 <code>5xx</code> 响应中<strong>可选</strong>。</li><li>无可靠时钟的服务器 <strong>MUST NOT</strong> 发送。</li><li>请求中的 <code>Date</code> 是可选的，客户端通常不发（<code>POST</code>/<code>PUT</code> 时可发）。</li><li>缓存收到无 <code>Date</code> 的响应时 <strong>MUST</strong> 自行补上接收时刻。</li></ul><p><code>Date</code> 是缓存年龄计算的基准，见<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>。</p><h2 id="时钟偏差" tabindex="-1">时钟偏差 <a class="header-anchor" href="#时钟偏差" aria-label="Permalink to &quot;时钟偏差&quot;">​</a></h2><p>HTTP 的缓存新鲜度计算<strong>依赖双方时钟</strong>，偏差直接导致缓存行为错误。规范的应对：</p><ul><li>优先使用<strong>相对时间</strong>（<code>Cache-Control: max-age</code>）而非绝对时间（<code>Expires</code>）——<code>max-age</code> 不受时钟偏差影响，这是它优先级更高的原因之一。</li><li><code>Age</code> 字段以秒计，同样是相对量。</li><li>缓存计算 <code>current_age</code> 时会取 <code>apparent_age</code>（本地接收时刻 − 响应 <code>Date</code>）与 <code>corrected_age</code>（<code>Age</code> + 传输耗时）中的<strong>较大值</strong>，以此抵消时钟慢的一侧。</li></ul><h2 id="last-modified-与-expires-的日期约束" tabindex="-1">Last-Modified 与 Expires 的日期约束 <a class="header-anchor" href="#last-modified-与-expires-的日期约束" aria-label="Permalink to &quot;Last-Modified 与 Expires 的日期约束&quot;">​</a></h2><ul><li><code>Last-Modified</code> <strong>MUST NOT</strong> 晚于响应的 <code>Date</code>。若存储的修改时间更晚，服务端 <strong>SHOULD</strong> 用 <code>Date</code> 值替代。</li><li><code>Expires</code> 若早于 <code>Date</code>，表示响应<strong>已经过期</strong>。</li><li>表示「永不过期」时，<code>Expires</code> 的推荐上限是<strong>不超过一年后</strong>——超过一年的值应改用 <code>Cache-Control: max-age</code>。</li><li>表示「立即过期」的规范写法是 <code>Expires: 0</code> 或任何无效日期——两者都会被解析为「已过期」。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>——ETag、验证器与 If-* 系列字段。</p>`,29)])])}const g=a(n,[["render",d]]);export{h as __pageData,g as default};
